  const br = data && data.bio_rules, colKey = br ? `${br.colours}|${(br.colours_job || {}).state}` : "";
  const key = `${kind}|${want}|${data && data.scan_version}|${want === "here" ? posId() : ""}|${colKey}`;
  if (!force && key === CL.key) return;
