const fuelJumpsCfg = () => { const v = store.get("fuelJumps", null), n = Number(v);
  return v != null && v !== "" && isFinite(n) && n > 0 ? Math.round(n) : null; };
const fuelUnderJumps = f => { const n = fuelJumpsCfg(), j = fuelJumps(f); return n != null && j != null && j < n; };
