  if (/^ai_/.test(q.code || "")) return `no phrase matched → <b>the AI failed</b>${esc(ai)}: ${esc(q.error)}`;
  if (q.command) return `matched “${esc(q.phrase)}” → ${esc(q.label || q.command)}, <b>but the answer failed</b>: ${esc(q.error)}`;
