  const langs = [...names.entries()].sort((a, b) => a[1].localeCompare(b[1])), want = sel.value || String(r.current || "en_GB").split("-")[0];
  sel.innerHTML = langs.map(([c, n]) => `<option value="${esc(c)}">${esc(n)}</option>`).join("");
